SET @qfin = LAST_INSERT_ID();

INSERT INTO quizzes (lesson_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, sort_order) VALUES
(@qfin, 'Jaký je správný způsob připojení k MariaDB v PHP?', 'mysql_connect()', 'new PDO("mysql:host=...;dbname=...;charset=utf8", ...)', 'new mysqli(...)', 'pg_connect()', 'b', 'PDO je doporučená abstraktní vrstva — podporuje prepared statements a více databází.', 1),
(@qfin, 'K čemu slouží PDO prepared statements?', 'Zrychlují dotazy', 'Zabraňují SQL injekci', 'Komprimují data', 'Ukládají výsledky do cache', 'b', 'Prepared statements oddělují SQL kód od dat — zabraňují SQL injekci.', 2),
(@qfin, 'Jak správně escapovat výstup proti XSS?', 'addslashes()', 'strip_tags()', 'htmlspecialchars($s, ENT_QUOTES, "UTF-8")', 'urlencode()', 'c', 'htmlspecialchars s ENT_QUOTES a UTF-8 převodí nebezpečné znaky na HTML entity.', 3),
(@qfin, 'Jaká cookie domain umožňí sdílení napříč subdoménami .vevit.fun?', 'domain=edu.vevit.fun', 'domain=.vevit.fun', 'domain=vevit.fun', 'domain=*.vevit.fun', 'b', 'Tečka před doménou (.vevit.fun) umožňuje sdílet cookie napříč všemi subdoménami.', 4),
(@qfin, 'Co dělá PHP trait?', 'Definuje konstantu', 'Umožňuje sdílet kód mezi třídami bez dědičnosti', 'Vytváří novou instanci', 'Importuje Composer balíček', 'b', 'Trait je mechanismus pro sdílení metod mezi třídami — alternativa k vícenásobné dědičnosti.', 5),
(@qfin, 'Jak vytvoříš bezpečný token pro reset hesla?', 'md5(time())', 'rand(0, 999999)', 'bin2hex(random_bytes(32))', 'sha1($userId)', 'c', 'bin2hex(random_bytes(32)) generuje kryptograficky bezpečný náhodný token.', 6),
(@qfin, 'Jak ověříš MIME typ nahraného souboru?', '$_FILES["file"]["type"]', 'pathinfo($name, PATHINFO_EXTENSION)', 'finfo_file(finfo_open(FILEINFO_MIME_TYPE), $tmp)', 'getimagesize()', 'c', 'finfo_file ověřuje skutečný MIME typ souboru — $_FILES["type"] pochází od klienta a je nespolehlivý.', 7),
(@qfin, 'Co znamená PDO::ATTR_EMULATE_PREPARES => false?', 'Emuluje prepared statements', 'Vypíná emulaci — native prepared statements na serveru', 'Povoluje SQL injekci', 'Zrychluje dotazy', 'b', 'Vypnutí emulace zaručí, že prepared statements běží nativně na databázovém serveru.', 8),
(@qfin, 'Jaký .htaccess RewriteRule přesměruje API na PHP backend?', 'RewriteRule ^api/(.*)$ index.php', 'RewriteRule ^api/(.*)$ api/index.php [QSA,L]', 'RewriteRule /api api.php', 'Redirect /api index.php', 'b', 'RewriteRule s QSA (předá query string) a L (poslední pravidlo) přesměruje API požadavky na PHP entry point.', 9),
(@qfin, 'K čemu slouží PHP spl_autoload_register?', 'Registruje Composer balíčky', 'Zaregistruje funkci, která automaticky načte třídu při prvním použití', 'Vytváří nové třídy', 'Přepíše existující třídu', 'b', 'spl_autoload_register umožňuje vlastní autoloading — třída se načte automaticky, když je poprvé použita.', 10);


